function initializeDialog() {
    const dialog = document.getElementById('delete-confirm-dialog');
    const deleteButtons = document.querySelectorAll('.delete-btn');
    let currentImageId = null;
    let triggerButton = null;

    deleteButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            triggerButton = e.target;
            currentImageId = button.dataset.imageId;
            dialog.showModal();
        });
    });

    dialog.addEventListener('close', () => {
        if (dialog.returnValue === 'delete') {
            handleDelete();
        }
        currentImageId = null;
        triggerButton = null;
    });

    const cancelButton = dialog.querySelector('[data-action="cancel"]');
    const deleteButton = dialog.querySelector('[data-action="delete"]');

    cancelButton.addEventListener('click', () => {
        dialog.close('cancel');
    });

    deleteButton.addEventListener('click', () => {
        dialog.close('delete');
    });

    dialog.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            dialog.close('cancel');
        }
    });

    function handleDelete() {
        const imageCard = document.querySelector(`[data-image-id="${currentImageId}"]`)?.closest('.image-card');

        if (imageCard) {
            imageCard.style.opacity = '0.5';
            imageCard.style.pointerEvents = 'none';

            setTimeout(() => {
                imageCard.remove();
            }, 300);
        }
    }
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeDialog);
} else {
    initializeDialog();
}

