const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const axePath = '/tmp/axe.min.js';
  const htmlFile = path.join(__dirname, 'index.html');
  const jsFile = path.join(__dirname, 'script.js');
  const cssFile = path.join(__dirname, 'styles.css');
  const html = fs.readFileSync(htmlFile, 'utf-8');
  const js = fs.readFileSync(jsFile, 'utf-8');
  const css = fs.readFileSync(cssFile, 'utf-8');

  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Build complete HTML with scripts
  const completeHtml = html.replace('</head>', `<style>${css}</style></head>`).replace('</body>', `<script>${js}</script></body>`);

  // Set content
  await page.setContent(completeHtml, { waitUntil: 'load' });

  // Test 1: Initial state - dialog should not be open
  let dialogOpen = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog.hasAttribute('open');
  });
  console.log('Test 1 - Dialog initially closed:', !dialogOpen);

  // Test 2: Trigger has "trigger" class
  let hasTriggerClass = await page.evaluate(() => {
    return document.querySelector('.trigger') !== null;
  });
  console.log('Test 2 - Delete buttons have "trigger" class:', hasTriggerClass);

  // Test 3: Click delete button and check dialog opens
  await page.click('.delete-btn');
  await page.waitForTimeout(100);
  dialogOpen = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog.hasAttribute('open');
  });
  console.log('Test 3 - Dialog opens on trigger click:', dialogOpen);

  // Test 4: Check if focus is in dialog
  let focusInDialog = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
