const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const axePath = '/tmp/axe.min.js';
  const htmlFile = path.join(__dirname, 'index.html');
  const jsFile = path.join(__dirname, 'script.js');
  const cssFile = path.join(__dirname, 'styles.css');
  const html = fs.readFileSync(htmlFile, 'utf-8');
  const js = fs.readFileSync(jsFile, 'utf-8');
  const css = fs.readFileSync(cssFile, 'utf-8');

  const browser = await chromium.launch();
  const page = await browser.newPage();

  const completeHtml = html.replace('</head>', `<style>${css}</style></head>`).replace('</body>', `<script>${js}</script></body>`);

  await page.setContent(completeHtml, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  // Get the violation details
  const result = await page.evaluate(async () => {
    return await window.axe.run();
  });

  const contrastViolations = result.violations.filter(v => v.id === 'color-contrast');

  console.log('Color contrast violations for card delete buttons:');
  contrastViolations.forEach(v => {
    v.nodes.forEach(node => {
      console.log('Target:', node.target);
      console.log('Issue:', node.failureSummary);
      console.log('---');
    });
  });

  // Check actual colors
  const colors = await page.evaluate(() => {
    const btn = document.querySelector('.delete-btn');
    const computed = window.getComputedStyle(btn);
    return {
      backgroundColor: computed.backgroundColor,
      color: computed.color,
      fontSize: computed.fontSize
    };
  });

  console.log('\nCard delete button computed styles:', colors);

  await browser.close();
})();
