     padding: var(--space-sm) var(--space-lg);
     border-radius: var(--radius-md);
     font-weight: 500;
     transition: all 0.2s ease;
     border: 1px solid transparent;
     cursor: pointer;
     font-size: 1rem;
 }

 .btn:focus-visible {
     outline: 2px solid var(--color-focus);
 }

 .btn-secondary {
