         dialog.close('cancel');
     });

     deleteButton.addEventListener('click', () => {
         dialog.close('delete');
     });

     dialog.addEventListener('keydown', (e) => {
         if (e.key === 'Escape') {
             dialog.close('cancel');
         }
     });

