    return dialog.contains(document.activeElement);
  });
  console.log(`✓ Focus in dialog: ${focusInDialog}`);

  await page.keyboard.press('Escape');
  await page.waitForTimeout(100);

  const dialogOpen2 = await page.evaluate(() => document.getElementById('delete-confirm-dialog').hasAttribute('open'));
  console.log(`✓ Escape closes dialog: ${!dialogOpen2}`);

  const focusRestored = await page.evaluate(() => {
    return document.activeElement.classList.contains('trigger');
  });
  console.log(`✓ Focus restored to trigger: ${focusRestored}`);

  // Test 5: Requirements
  const requirements = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return {
      dialogClosed: !dialog.hasAttribute('open'),
      triggerClass: document.querySelectorAll('.trigger').length > 0,
      dialogHasLabel: dialog.hasAttribute('aria-labelledby'),
      nativeDialog: dialog.tagName === 'DIALOG'
    };
  });

  console.log(`\n✓ Dialog closed by default: ${requirements.dialogClosed}`);
